{
  "contract": "ReservaX",
  "closure": {
    "site_function": "withdraw",
    "site_call": ".call",
    "functions": [
      "withdraw",
      "_beforeTokenTransfer"
    ],
    "justification": "These functions interact with the exposed storage variables _status, withdrawNine, and withdrawTen."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "_beforeTokenTransfer"
    ],
    "nesting_bound": {
      "withdraw": 1
    }
  },
  "phases": {
    "function": "withdraw",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_external_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_external_call",
      "to_marker": "after_external_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_external_call",
      "to_marker": "end"
    },
    "linearization_point": "after_external_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount in transit during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "withdrawNine + withdrawTen == _totalSupply[9] + _totalSupply[10] + inFlight",
    "stable_formula": "withdrawNine + withdrawTen == _totalSupply[9] + _totalSupply[10]",
    "kind": "additive"
  },
  "composition": {
    "target_property": "withdrawNine <= _totalSupply[9] && withdrawTen <= _totalSupply[10]",
    "rule": "The exposure invariant ensures that the sum of withdrawNine and withdrawTen does not exceed the total supply during the callback window."
  }
}
